from PySide6.QtWidgets import QCheckBox, QComboBox, QFormLayout, QLineEdit, QPushButton, QVBoxLayout, QWidget, QFileDialog
class SettingsPage(QWidget):
    def __init__(self, settings, save):
        super().__init__(); self.settings = settings; self.save = save; layout = QVBoxLayout(self); self.form = QFormLayout(); self.folder = QLineEdit(settings["default_folder"]); self.quality = QComboBox(); self.quality.addItems(["720p HD (MP4)","1080p Full HD (MP4)","2K Quad HD (1440p MP4)","4K Ultra HD (2160p MP4)","MP3 Audio (320 kbps)"]); self.quality.setCurrentText(settings["default_quality"]); self.audio = QComboBox(); self.audio.addItems(["128 kbps","320 kbps"]); self.audio.setCurrentText(settings["audio_quality"]); self.subtitles = QCheckBox(); self.subtitles.setChecked(settings["subtitles"]); self.notifications = QCheckBox(); self.notifications.setChecked(settings["notifications"]); self.form.addRow("Default folder", self.folder); self.form.addRow("Default quality", self.quality); self.form.addRow("Audio quality", self.audio); self.form.addRow("Subtitles", self.subtitles); self.form.addRow("Notifications", self.notifications); layout.addLayout(self.form); save_button = QPushButton("Save Settings"); save_button.setObjectName("Primary"); save_button.clicked.connect(self.save_settings); layout.addWidget(save_button); layout.addStretch()
    def save_settings(self): self.settings.update(default_folder=self.folder.text(), default_quality=self.quality.currentText(), audio_quality=self.audio.currentText(), subtitles=self.subtitles.isChecked(), notifications=self.notifications.isChecked()); self.save(self.settings)
